char *get_ls_result(const char *dir_path) {
    // Check if dir_path is valid and not a malicious path
    if (!dir_path || strlen(dir_path) == 0) {
        return strdup("");
    }

    // Normalize the path to avoid path traversal
    char resolved_path[1024];
    if (realpath(dir_path, resolved_path) == NULL) {
        return strdup("");
    }

