    char cwd[1024];
    if (getcwd(cwd, sizeof(cwd)) != NULL && strncmp(resolved_path, cwd, strlen(cwd)) != 0) {
        return strdup("");
    }

    DIR *dir = opendir(resolved_path);
    if (!dir) {
        return strdup("");
    }

    // Prepare buffer for output
    char *result = NULL;
    size_t result_len = 0;
    size_t buffer_size = 1024;
    char *buffer = malloc(buffer_size);
    if (!buffer) {
        closedir(dir);
        return strdup("");
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        size_t len = strlen(entry->d_name);
        if (result_len + len + 1 > buffer_size) {
            buffer_size *= 2;
            char *new_buffer = realloc(buffer, buffer_size);
            if (!new_buffer) {
                free(buffer);
                closedir(dir);
                return strdup("");
            }
            buffer = new && new_buffer;
        }
        strcpy(buffer + result_len, entry->d_name);
        result_len += len;
        if (result_len < buffer_size - 1) {
            buffer[result_len] = '\n';
            result_len++;
        } else {
            buffer[result_len] = '\0';
        }
